messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <title>3D Race with Three.js</title>
  <style>
    body { margin: 0; overflow: hidden; background: #000; }
    #container { position: relative; width: 100%; height: 100%; }
  </style>
</head>
<body>
  <div id="container"></div>
  <script type="module">
    import * as THREE from './three.module.js';

    let scene, camera, renderer, sphere1, sphere2, ground, sky;
    let car1, car2;

    // Initialize scene, camera, renderer
    function init() {
      scene = new THREE.Scene();
      camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
      renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('container') });
      renderer.setPerspective(camera, window.innerWidth / window.innerHeight, 0.3, 10);
      document.body.appendChild(renderer.domElement);

      // Ground and sky
      const groundGeometry = new THREE.PlaneGeometry(200, 200);
      const groundMaterial = new THREE.MeshStandardMaterial({ color: 0x004080 });
      const ground = new THREE.Mesh(groundGeometry, groundMaterial);
      ground.rotation.x = -Math.PI/2;
      scene.add(ground);

      const skyGeometry = new THREE.CylinderGeometry(10, 10, 100);
      const skyMaterial = new THREE.MeshStandardMaterial({ color: 0x87CEEB });
      const sky = new THREE.Mesh(skyGeometry, skyMaterial);
      scene.add(sky);

      // Cars
      sphere1 = new THREE.Sphere({ radius: 2, material: new THREE.MeshStandardMaterial({ color: 0xFF0000, rubber: true }) };
      sphere2 = new THREE.Sphere({ radius: 2, material: new THREE.MeshStandardMaterial({ color: 0x0000FF, rubber: true }) };

      // Race track
      const trackGeometry = new THREE.TorusSurfaceGeometry(1, 10, 100);
      const trackMaterial = new THREE.MeshStandardMaterial({ color: 0xAAAAAA, metal: true });
      const track = new THREE.Mesh(trackGeometry, trackMaterial);
      scene.add(track);

      // Car positions
      car1 = new THREE.Mesh(sphere1, new THREE.MeshStandardMaterial({ color: 0xFF0000 }));
      car2 = new THREE.Mesh(sphere2, new THREE.MeshStandardMaterial({ color: 0x0000FF }));
      car1.position.set(5, 5, 5);
      car2.position.set(15, 5, 5);

      // Animation loop
      function animate() {
        requestAnimationFrame(animate);
        // Move cars
        car1.position.set(car1.position.x + 0.1, car1.position.y + 0.1, car1.position.z + 0.1);
        car2.position.set(car2.position.x - 0.1, car2.position.y + 0.1, car2.position.z + 0.1);

        // Reset loop
        if (car1.position.z >= 20 && car2.position.z >= 20) {
          car1.position.set(0, 0, 0);
          car2.position.set(20, 0, 0);
        }

        // Render
        renderer.render(scene, camera);
      }

      animate();
    }

    init();
  </script>
</body>
</html>
```
